-- Load official college facts (round 1). Re-runnable: merges into colleges.facts.
update public.colleges set facts = coalesce(facts, '{}'::jsonb) || '{"as_of": "Oct 27, 2026 (Scorecard Jun 2026 release; costs NCES 2024-25)", "stats": {"undergrad_enrollment": 34454, "admit_rate": 0.1564, "grad_rate_6yr": 0.9319, "retention_rate": 0.9747, "student_faculty_ratio": "11:1", "in_state_tuition_fees": 17736, "in_state_cost_of_attendance": 36932, "avg_net_price_all": 14362, "median_earnings_10yr": 92832, "drive_miles": 366, "drive_hours": 6.5}, "net_price_by_income": {"0-30000": 3155, "30001-48000": 3372, "48001-75000": 5768, "75001-110000": 13888, "110001-plus": 28625}, "business": {"school": "Stephen M. Ross School of Business (BBA)", "admission_model": "Direct first-year admission since Fall 2024: choose Ross on the Common App and submit the Ross BBA Admissions Portfolio (SlideRoom). EA Nov 1; RD and portfolio Feb 1.", "class_size": "About 675 BBA graduates a year (IPEDS 2024-25 completions)", "academic_feel": "One general BBA (no separate majors). Team-based core with the Ross Integrative Semester in junior year and action-based learning for every student.", "recruiting_and_outcomes": "Business grads’ median earnings $96,806 one year after graduating (Scorecard field of study).", "signature_programs": ["Ross Integrative Semester (junior-year integrated core + entrepreneurial challenge)", "Action-based learning in sophomore and junior core; ~75% do more via REAL", "MAP capstone team projects for sponsor organizations"], "aacsb": true}, "sources": [{"label": "College Scorecard", "url": "https://collegescorecard.ed.gov/school/?170976-University-of-Michigan-Ann-Arbor", "year": "2026 release"}, {"label": "NCES College Navigator", "url": "https://nces.ed.gov/collegenavigator/?id=170976", "year": "2024-25"}, {"label": "Ross first-year applicants", "url": "https://michiganross.umich.edu/undergraduate/bba/admissions/first-year-applicants", "year": "2026"}, {"label": "Ross BBA core", "url": "https://rossweb.bus.umich.edu/academics/curriculum/core-curriculum/bba/", "year": "current"}]}'::jsonb where id = '00000000-0000-4000-a000-000000000001';
